-- 236: The five Great Lesson strands as storylines in the Strands tab of both Cosmic Education language spaces (Dustin, 2026-11-07).
-- The Strands tab lists named sequences through stages, so each strand becomes one storyline across its stages GB-0 to GB-3 (GB-4 to GB-6 only hand off
-- to other models and stay out). 5 storylines per language space, 4 stations each. Status 'proposed'. Wording comes from the draft's own strand text and
-- essential questions (the German space uses the draft's German). Nobody has reviewed any of it.
-- Generated by scripts/generate_cosmic_education_threads_migration.mjs. Running this twice changes nothing.
-- Rollback: DELETE FROM lpm_threads WHERE slug LIKE 'cosmic-%' AND project_id IN (SELECT id FROM projects WHERE slug IN ('cosmic-education-lpm-en','cosmic-education-lpm-de'));
SET search_path = public, extensions;
DO $MIGRATION$
DECLARE v_proj UUID; v_branch UUID;
BEGIN
  SELECT p.id, b.id INTO v_proj, v_branch FROM projects p JOIN branches b ON b.project_id = p.id AND b.is_trunk WHERE p.slug = 'cosmic-education-lpm-en';
  IF v_proj IS NULL THEN RAISE EXCEPTION 'cosmic-education-lpm-en missing'; END IF;
  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('8cc8f02b-14dc-5760-ab62-88f4e7b8b775', v_proj, v_branch, 'cosmic-story-of-the-universe', $J$The Story of the Universe$J$, 'vertical', '41969baa-d0ce-5bb9-a515-ddd4f3ede140', $J$Where did everything come from, and why does it hold together?$J$, $J$Montessori's First Great Lesson: the formation of the universe, the solar system, and Earth, told as one dramatic impressionistic narrative — matter, energy, gravity, and the laws that govern them, presented as a "big picture" before any single science subject (astronomy, chemistry, physics, geography) is studied in isolation. The throughline concept (Interconnectedness — everything in the physical universe operates by shared, discoverable laws) is introduced narratively in Lower Elementary and deepens into real Earth-science and physical-science content as children's own "Going Out" research follows their questions outward from the story.$J$, $J$A single story can hold astronomy, chemistry, geography, and physics together without flattening any of them — what does a class lose, and what does it gain, by starting from one big story instead of four separate subjects?$J$, $J$Built from the cosmic-education-k12 draft's strand text and essential questions. No expert has reviewed it. Montessori's own scope is ages 6 to 12; the draft calls the progression a designed thought experiment that has not been tested against children's reasoning.$J$, '[]'::jsonb, 'proposed')
  ON CONFLICT (project_id, slug) DO NOTHING;
