  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
  VALUES ('235ab7dc-5dd7-57b6-9575-913b027dc491', '8cc8f02b-14dc-5760-ab62-88f4e7b8b775', 'a607e3c1-8b2f-58c2-9e2a-6641ef10f571', 4, $J$Lower Secondary I, ages 10–12: The Laws That Hold, Everywhere$J$, '41969baa-d0ce-5bb9-a515-ddd4f3ede140', NULL)
