  VALUES ('6a7b7b2d-1ae4-5247-9ba3-f0868e5719bc', 'e36d6905-38cf-51b0-be37-0959e222d155', '526da625-d751-50b0-8195-db7d4c3bf8bf', 3, $J$Primary II, ages 8–10: The Clock of Eras and Going Out Into Biology$J$, '77cc800e-5b91-588c-b9e8-343e50435021', $J$deepens$J$)
  ON CONFLICT (thread_id, sequence) DO NOTHING;
  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
  VALUES ('0a075b72-3706-5267-a83b-254c49097ea5', 'e36d6905-38cf-51b0-be37-0959e222d155', '31ab34da-ccd7-5220-b7ab-43843df78d6c', 4, $J$Lower Secondary I, ages 10–12: One Role or One Consequence? Naming the Tension$J$, '77cc800e-5b91-588c-b9e8-343e50435021', NULL)
