  VALUES ('ceea3a4a-289c-5e5e-9569-5b640f7dd6b2', '7775668d-9294-50f7-85ad-62edbf1b318b', '93fec4d5-636f-5853-8885-94c7bb43f5fb', 3, $J$Primary II, ages 8–10: One Need, Many Solutions$J$, 'cab10790-5d51-5768-a567-df0ec9aca67d', $J$deepens$J$)
