  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
  VALUES ('48f1bd8f-6441-5a53-a0a3-4efeed3e7f7f', '7775668d-9294-50f7-85ad-62edbf1b318b', '0e4e1877-f918-5732-8caa-6a5b1fbb1cf2', 4, $J$Lower Secondary I, ages 10–12: Needs, Cooperation, and Fairness$J$, 'cab10790-5d51-5768-a567-df0ec9aca67d', NULL)
