  ON CONFLICT (thread_id, sequence) DO NOTHING;
  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
  VALUES ('276e430d-165c-5aac-833e-f335b59c0603', '015b5582-4827-5868-be22-c072970598a5', 'cb5fc029-f42f-583d-b3d5-7bead8a6eb83', 2, $J$Primary I, ages 6–8: The Story of Signs, First Telling$J$, '4169768d-db96-5f05-a337-668ed11d0a0f', $J$deepens$J$)
