  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
  VALUES ('c98f6429-f81d-5a37-80e7-c58dd1df7149', '015b5582-4827-5868-be22-c072970598a5', '40777506-9852-53aa-bf6a-027879bc3658', 4, $J$Lower Secondary I, ages 10–12: What Writing Made Possible$J$, '4169768d-db96-5f05-a337-668ed11d0a0f', NULL)
