  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('f489f017-861c-53e8-8f4a-dd1ff93eeab5', v_proj, v_branch, 'cosmic-story-of-numbers', $J$The Story of Numbers$J$, 'vertical', '20cfab66-d5e7-5b8d-a628-e09a6f6d77f2', $J$Who invented numbers, and could counting have worked differently?$J$, $J$Montessori's Fifth Great Lesson: how humans came to represent quantity with symbols — tallies, place value, zero — as a historical human achievement, not a fact of nature waiting to be discovered ready-made. The strand that makes explicit a claim this LPM treats as a genuine finding, not an assumption carried in from outside: that mathematics, told this way, is itself one of the Great Stories, structurally parallel to oSci's own selection-retention account of how minds, cultures, and the history of science each search for better ideas by building on a remembered pool of past solutions rather than starting from nothing each time.$J$, $J$A base-10 place-value system with a zero is not the only way humans have ever represented quantity — other systems used different bases, or no place value at all, or no zero. If numbers themselves have a history and could have gone differently, what does that change about how a class should think about 'discovering' versus 'inventing' in mathematics?$J$, $J$Built from the cosmic-education-k12 draft's strand text and essential questions. No expert has reviewed it. Montessori's own scope is ages 6 to 12; the draft calls the progression a designed thought experiment that has not been tested against children's reasoning.$J$, '[]'::jsonb, 'proposed')
  ON CONFLICT (project_id, slug) DO NOTHING;
