  VALUES ('ee7db097-320e-5bf5-b0a9-e5678255bce7', 'f489f017-861c-53e8-8f4a-dd1ff93eeab5', 'a1aed355-88e8-52a4-8205-45bdca03ca59', 4, $J$Lower Secondary I, ages 10–12: Mathematics as a Great Story$J$, '20cfab66-d5e7-5b8d-a628-e09a6f6d77f2', NULL)
