  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('e99c9617-576e-594b-be0b-acc4b5035a9e', v_proj, v_branch, 'cosmic-story-of-the-universe', $J$Die Geschichte des Universums$J$, 'vertical', 'a1d96e1e-fcc7-5991-96d2-46fed5d7ba42', $J$Woher kommt alles, und warum hält es zusammen?$J$, $J$Montessoris Erste Große Erzählung: die Entstehung des Universums, des Sonnensystems und der Erde, erzählt als eine dramatische, impressionistische Erzählung — Materie, Energie, Schwerkraft und die sie bestimmenden Gesetze, dargestellt als „großes Bild", bevor ein einzelnes naturwissenschaftliches Fach (Astronomie, Chemie, Physik, Geographie) isoliert behandelt wird. Die Leitidee (Vernetztheit — alles im physikalischen Universum folgt gemeinsamen, erforschbaren Gesetzen) wird in der Unterstufe erzählerisch eingeführt und vertieft sich zu echten erd- und physikwissenschaftlichen Inhalten, sobald Kinder ihren eigenen Fragen durch „Erkundungsgänge" nachgehen.$J$, $J$Eine einzige Erzählung kann Astronomie, Chemie, Geographie und Physik zusammenhalten, ohne eines dieser Fächer zu verflachen — was verliert und was gewinnt eine Klasse, wenn sie mit einer großen Erzählung statt mit vier getrennten Fächern beginnt?$J$, $J$Aus Strangtext und Leitfragen des Entwurfs cosmic-education-k12 zusammengestellt. Keine Fachperson hat es geprüft. Montessoris eigener Geltungsbereich sind die Altersstufen 6 bis 12; der Entwurf nennt die Progression ein Gedankenexperiment, das noch nicht am Denken von Kindern geprüft wurde.$J$, '[]'::jsonb, 'proposed')
  ON CONFLICT (project_id, slug) DO NOTHING;
