  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('9d741c47-a55a-5a7a-91ad-4b699ae0944c', v_proj, v_branch, 'cosmic-story-of-life', $J$Die Geschichte des Lebens$J$, 'vertical', '3297de0f-689f-5f64-933d-c2ce7b81c54e', $J$Wie hat sich das Leben auf der Erde verändert, und was bedeutet „Veränderung“ über so gewaltige Zeiträume hinweg?$J$, $J$Montessoris Zweite Große Erzählung: das Erscheinen und die Veränderung des Lebens auf der Erde über geologische Zeiträume hinweg, erzählt anhand der Zeitleiste des Lebens und der Erdzeituhr — Pflanzen und Tiere, die im Paläozoikum, Mesozoikum und Känozoikum erscheinen, sich verändern und oft wieder verschwinden. Hier trifft die affektive Rahmung der „Kosmischen Aufgabe" (jedes Lebewesen erfüllt eine Aufgabe im Dienst des Ganzen) am unmittelbarsten auf die von der Evolutionsbiologie hart erarbeitete Unterscheidung zwischen legitimer und nicht legitimer zweckgerichteter Sprache — dieser Strang benennt diese Spannung in Stufe GB-3 ausdrücklich, statt sie implizit zu lassen.$J$, $J$Montessoris Kosmische Aufgabe sagt, jedes Lebewesen habe eine Rolle im Dienst des Ganzen. Eine Biologin sagt, ein Merkmal bestehe fort, weil es früheren Generationen beim Überleben und Fortpflanzen geholfen hat, nicht weil es gebraucht wurde. Sind das zwei Formulierungen derselben Idee, oder wirklich unterschiedliche Aussagen — und ist es wichtig, welche ein Kind am Ende glaubt?$J$, $J$Aus Strangtext und Leitfragen des Entwurfs cosmic-education-k12 zusammengestellt. Keine Fachperson hat es geprüft. Montessoris eigener Geltungsbereich sind die Altersstufen 6 bis 12; der Entwurf nennt die Progression ein Gedankenexperiment, das noch nicht am Denken von Kindern geprüft wurde.$J$, '[]'::jsonb, 'proposed')
  ON CONFLICT (project_id, slug) DO NOTHING;
