  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('ff782f1a-66ac-505b-8c30-946024e30830', v_proj, v_branch, 'cosmic-story-of-humans', $J$Die Geschichte des Menschen$J$, 'vertical', 'db706eef-d166-5f71-a2e8-58a5486eff3a', $J$Was brauchen alle Menschen, und wie unterschiedlich haben Menschen dieselben Bedürfnisse erfüllt?$J$, $J$Montessoris Dritte Große Erzählung: das Erscheinen des Menschen, die Zeitleiste der Hominiden und — ihr eigenes, namentlich benanntes Ordnungsprinzip — die Grundbedürfnisse des Menschen (physisch: Nahrung, Unterkunft, Verteidigung, Transport; geistig-seelisch: Kunst, Religion, Musik, ein Gefühl von Bedeutsamkeit), die jede menschliche Kultur zu jeder Epoche auf unterschiedliche Weise erfüllt hat. Der Strang, in dem die eigene kulturübergreifende Rahmung der Kosmischen Erziehung — ein Bedürfnis, viele gültige Lösungen — strukturell parallel zur eigenen Behandlung universeller menschlicher Bedürfnisse und variabler kultureller Lösungen in der Evolutionären Anthropologie verläuft.$J$, $J$Jede bekannte menschliche Gruppe musste dieselbe Handvoll Probleme lösen — Nahrung, Unterkunft, Sicherheit, Sinn. Eine Klasse, die vergleicht, wie drei sehr unterschiedliche Kulturen „Unterkunft“ gelöst haben, tut etwas, das die Evolutionäre Anthropologie auch mit „Kooperation“ oder „Fairness“ tut — was ändert sich, und was bleibt gleich, wenn dieselbe vergleichende Methode auf ein physisches statt ein soziales Bedürfnis angewendet wird?$J$, $J$Aus Strangtext und Leitfragen des Entwurfs cosmic-education-k12 zusammengestellt. Keine Fachperson hat es geprüft. Montessoris eigener Geltungsbereich sind die Altersstufen 6 bis 12; der Entwurf nennt die Progression ein Gedankenexperiment, das noch nicht am Denken von Kindern geprüft wurde.$J$, '[]'::jsonb, 'proposed')
  ON CONFLICT (project_id, slug) DO NOTHING;
