  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('2a928ec0-26a1-558b-b943-95f7c530d994', v_proj, v_branch, 'cosmic-story-of-language', $J$Die Geschichte der Sprache$J$, 'vertical', '3bc03b9d-5f9d-591c-95e5-7ad870118b88', $J$Wie kamen Zeichen auf einer Oberfläche dazu, Bedeutung zu tragen, und was änderte sich, sobald sie es konnten?$J$, $J$Montessoris Vierte Große Erzählung: wie Menschen dazu kamen, Laute und Ideen durch willkürliche Zeichen darzustellen — Zeichen, Bildschrift, Alphabete — und wie diese eine Erfindung es ermöglichte, Wissen über Generationen hinweg anzuhäufen und weiterzugeben, über das hinaus, was das Gedächtnis allein tragen konnte.$J$, $J$Jedes Schriftsystem, das Menschen je erfunden haben, nutzt willkürliche, gemeinsam vereinbarte Zeichen — nichts an der Form des Buchstabens „A“ macht seine Bedeutung selbstverständlich. Was gewinnt eine Klasse, wenn sie mehrere echte Schriftsysteme nebeneinander vergleicht, statt das eigene als natürlich oder selbstverständlich zu behandeln?$J$, $J$Aus Strangtext und Leitfragen des Entwurfs cosmic-education-k12 zusammengestellt. Keine Fachperson hat es geprüft. Montessoris eigener Geltungsbereich sind die Altersstufen 6 bis 12; der Entwurf nennt die Progression ein Gedankenexperiment, das noch nicht am Denken von Kindern geprüft wurde.$J$, '[]'::jsonb, 'proposed')
