  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, explained_by_element_id, connecting_idea, narrative, teaching_prompt, evidence_note, gaps, status)
  VALUES ('2f3e00ea-0fd6-59d1-89fa-9859ff3b2fb2', v_proj, v_branch, 'cosmic-story-of-numbers', $J$Die Geschichte der Zahlen$J$, 'vertical', 'be63cb60-5a7b-52e2-bcdc-ce85dcd976a7', $J$Wer hat die Zahlen erfunden, und hätte das Zählen auch anders funktionieren können?$J$, $J$Montessoris Fünfte Große Erzählung: wie Menschen dazu kamen, Mengen mit Symbolen darzustellen — Strichlisten, Stellenwertsystem, die Null — als eine historische menschliche Errungenschaft, keine bereits fertige Tatsache der Natur. Der Strang, der eine Behauptung ausdrücklich macht, die dieses Modell als echten Befund behandelt: dass Mathematik, so erzählt, selbst eine der Großen Erzählungen ist.$J$, $J$Ein Zehnersystem mit Stellenwert und einer Null ist nicht die einzige Art, wie Menschen je Mengen dargestellt haben — andere Systeme nutzten andere Basen, kein Stellenwertsystem oder keine Null. Wenn Zahlen selbst eine Geschichte haben und auch anders hätten verlaufen können, was ändert das daran, wie eine Klasse über „Entdecken“ gegenüber „Erfinden“ in der Mathematik denken sollte?$J$, $J$Aus Strangtext und Leitfragen des Entwurfs cosmic-education-k12 zusammengestellt. Keine Fachperson hat es geprüft. Montessoris eigener Geltungsbereich sind die Altersstufen 6 bis 12; der Entwurf nennt die Progression ein Gedankenexperiment, das noch nicht am Denken von Kindern geprüft wurde.$J$, '[]'::jsonb, 'proposed')
